.deal-bar{background:linear-gradient(145deg,rgba(255,255,255,.09),rgba(255,255,255,.03))!important;border:1px solid rgba(56,189,248,.3)!important;border-radius:10px!important;box-shadow:0 18px 44px rgba(0,0,0,.45),inset 0 1px 0 rgba(255,255,255,.14)!important}.deal-timer,.deal-timer *{background:#38bdf822!important;border:1px solid #38bdf866!important;color:#38bdf8!important;border-radius:4px!important}.cod-note{color:#38bdf8!important;text-align:center}
.pb-ofraw .field input,.pb-ofraw .field select{width:100%}
.gthumbs{display:flex;gap:10px;flex-wrap:wrap}.gthumbs img{flex:0 0 76px!important;width:76px!important;height:76px!important;object-fit:cover;opacity:.8}.gthumbs img.on,.gthumbs img:hover{opacity:1}
.pb-colin:has(#gmain)>.pb-w{margin-bottom:12px!important}.pbox,.pb-colin:has(#gmain){overflow:hidden}#gmain{border-radius:8px;transition:transform .6s cubic-bezier(.2,.8,.2,1)}.pb-colin:has(#gmain):hover #gmain{transform:scale(1.02)}
.pb-col:has(#gmain){align-self:flex-start}@media(min-width:900px){.pb-col:has(#gmain){position:sticky;top:90px}}
.tp-trust{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.tp-trust>div{display:flex;flex-direction:column;gap:3px;padding:12px 14px;background:linear-gradient(145deg,rgba(255,255,255,.09),rgba(255,255,255,.03));border:1px solid rgba(56,189,248,.3);border-radius:4px;box-shadow:none}.tp-trust b{color:#e2e8f0!important;font-size:14px}.tp-trust small{color:#94a3b8!important;font-size:12px}.tp-trust i{width:22px;height:4px;border-radius:4px;background:#38bdf8;margin-bottom:4px}@media(max-width:767px){.tp-trust{grid-template-columns:repeat(2,1fr)}}
.tp-buybar{display:none}@media(max-width:767px){.tp-buybar{position:fixed;left:0;right:0;bottom:0;border-radius:10px 10px 0 0;z-index:9990;display:flex;align-items:center;justify-content:space-between;gap:12px;padding:10px 14px;background:linear-gradient(145deg,rgba(255,255,255,.09),rgba(255,255,255,.03));border:1px solid rgba(56,189,248,.3);box-shadow:0 -8px 30px rgba(0,0,0,.25);transition:transform .35s,opacity .35s}.tp-buybar.off{transform:translateY(140%);opacity:0;pointer-events:none}.tp-buybar .bb-p small{display:block;color:#94a3b8;font-size:12px}.tp-buybar .bb-p b{color:#38bdf8;font-size:21px}.tp-buybar .bb-btn{flex:none;padding:13px 26px;border-radius:8px;font-weight:900;font-size:16px;text-decoration:none;color:#04202e!important;background:#38bdf8;box-shadow:none;}body{padding-bottom:84px}.pb-colin:has(#gmain){padding:12px!important}}
